func restoreIpAddresses(s string) []string {
	n := len(s)
	res := []string{}
	path := []string{}
	ok := func(a, b int) bool {
		if b-a+1 > 3 {
			return false
		}
		if b-a+1 > 1 && s[a] == '0' {
			return false
		}
		v, _ := strconv.Atoi(s[a : b+1])
		return v <= 255
	}
	var dfs func(start int)
	dfs = func(start int) {
		if len(path) == 4 {
			if start == n {
				res = append(res, strings.Join(path, "."))
			}
			return
		}
		for i := start; i < start+3 && i < n; i++ {
			if !ok(start, i) {
				break
			}
			path = append(path, s[start:i+1])
			dfs(i + 1)
			path = path[:len(path)-1]
		}
	}
	if n >= 4 && n <= 12 {
		dfs(0)
	}
	return res
}

