func candy(ratings []int) int {
	n := len(ratings)
	cnt := make([]int, n)
	for i := range cnt {
		cnt[i] = 1
	}
	for i := 1; i < n; i++ {
		if ratings[i] > ratings[i-1] {
			cnt[i] = cnt[i-1] + 1
		}
	}
	for i := n - 2; i >= 0; i-- {
		if ratings[i] > ratings[i+1] && cnt[i+1]+1 > cnt[i] {
			cnt[i] = cnt[i+1] + 1
		}
	}
	sum := 0
	for _, v := range cnt {
		sum += v
	}
	return sum
}

