func eraseOverlapIntervals(intervals [][]int) int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][1] < intervals[j][1] })
	removed := 0
	end, has := 0, false
	for _, it := range intervals {
		if !has || it[0] >= end {
			end, has = it[1], true
		} else {
			removed++
		}
	}
	return removed
}

